import React, { useState, useRef, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useTheme } from '../context/ThemeContext';
import ThemeToggle from './ThemeToggle';
import { FiUser, FiLogOut, FiShoppingBag, FiPlusCircle, FiSearch } from 'react-icons/fi';

const Header = () => {
    const { user, logout } = useAuth();
    const { darkMode } = useTheme();
    const navigate = useNavigate();
    const [searchTerm, setSearchTerm] = useState('');
    const [menuOpen, setMenuOpen] = useState(false);
    
    const timeoutRef = useRef(null);
    const menuContainerRef = useRef(null);

    const handleSearch = (e) => {
        e.preventDefault();
        navigate(`/?search=${encodeURIComponent(searchTerm)}`);
    };

    const openMenu = () => {
        if (timeoutRef.current) {
            clearTimeout(timeoutRef.current);
            timeoutRef.current = null;
        }
        setMenuOpen(true);
    };

    const closeMenu = () => {
        if (timeoutRef.current) {
            clearTimeout(timeoutRef.current);
        }
        timeoutRef.current = setTimeout(() => {
            setMenuOpen(false);
        }, 300);
    };

    const cancelClose = () => {
        if (timeoutRef.current) {
            clearTimeout(timeoutRef.current);
            timeoutRef.current = null;
        }
    };

    useEffect(() => {
        return () => {
            if (timeoutRef.current) {
                clearTimeout(timeoutRef.current);
            }
        };
    }, []);

    return (
        <header className="bg-white dark:bg-dark-bg border-b border-gray-200 dark:border-dark-border text-gray-800 dark:text-dark-text shadow-sm sticky top-0 z-50 transition-colors">
            <div className="container mx-auto px-4 py-3">
                <div className="flex items-center justify-between flex-wrap gap-3">
                    <Link to="/" className="flex items-center space-x-2">
                        <div className="w-10 h-10 bg-gradient-to-r from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center shadow-md">
                            <svg className="w-6 h-6 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z" />
                                <path d="M8 4v16" />
                                <path d="M16 4v16" />
                                <path d="M4 8h4" />
                                <path d="M4 16h4" />
                                <path d="M4 12h16" />
                                <path d="M16 8h4" />
                                <path d="M16 16h4" />
                            </svg>
                        </div>
                        <div>
                            <span className="text-lg font-bold bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent">InterConectados</span>
                            <span className="text-xs text-gray-500 dark:text-gray-400 hidden sm:block">Conectando pessoas</span>
                        </div>
                    </Link>

                    <form onSubmit={handleSearch} className="flex-1 max-w-md">
                        <div className="relative">
                            <input
                                type="text"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                placeholder="Buscar produtos..."
                                className="w-full px-4 py-2 pl-10 rounded-lg bg-gray-100 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 text-gray-800 dark:text-dark-text focus:outline-none focus:ring-2 focus:ring-blue-500 transition"
                            />
                            <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                        </div>
                    </form>

                    <nav className="flex items-center space-x-4">
                        <ThemeToggle />
                        
                        {user ? (
                            <>
                                {user.type === 'vendedor' && (
                                    <Link to="/create-product" className="flex items-center space-x-1 bg-blue-600 text-white px-3 py-2 rounded-lg hover:bg-blue-700 transition">
                                        <FiPlusCircle />
                                        <span className="hidden sm:inline">Anunciar</span>
                                    </Link>
                                )}
                                <Link to={user.type === 'vendedor' ? '/seller/dashboard' : '/buyer/dashboard'} className="hover:text-blue-600 dark:hover:text-blue-400 transition">
                                    <FiShoppingBag size={20} />
                                </Link>
                                
                                <div 
                                    ref={menuContainerRef}
                                    className="relative"
                                    onMouseEnter={openMenu}
                                    onMouseLeave={closeMenu}
                                >
                                    <button className="flex items-center space-x-2 hover:text-blue-600 dark:hover:text-blue-400 transition px-2 py-1 rounded">
                                        <span className="text-sm hidden sm:inline">{user.name}</span>
                                    </button>
                                    
                                    {menuOpen && (
                                        <div 
                                            className="absolute right-0 mt-2 w-48 bg-white dark:bg-dark-card rounded-lg shadow-lg py-2 z-50 border border-gray-200 dark:border-dark-border"
                                            onMouseEnter={cancelClose}
                                            onMouseLeave={closeMenu}
                                        >
                                            <Link
                                                to="/profile"
                                                className="flex items-center space-x-2 px-4 py-2 hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-700 dark:text-dark-text transition"
                                                onClick={() => setMenuOpen(false)}
                                            >
                                                <FiUser size={16} />
                                                <span>Meu Perfil</span>
                                            </Link>
                                            <button
                                                onClick={() => {
                                                    logout();
                                                    setMenuOpen(false);
                                                }}
                                                className="flex items-center space-x-2 px-4 py-2 hover:bg-gray-100 dark:hover:bg-gray-800 w-full text-left text-gray-700 dark:text-dark-text transition"
                                            >
                                                <FiLogOut size={16} />
                                                <span>Sair</span>
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </>
                        ) : (
                            <>
                                <Link to="/login" className="flex items-center space-x-1 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition">
                                    <FiUser />
                                    <span>Entrar</span>
                                </Link>
                                <Link to="/register" className="flex items-center space-x-1 border border-gray-300 dark:border-gray-600 px-4 py-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition">
                                    <span>Cadastrar</span>
                                </Link>
                            </>
                        )}
                    </nav>
                </div>
            </div>
        </header>
    );
};

export default Header;
